345	    /**
346	     * Gets the name of the node to be used for the given parameters in the Site Map.
347	     *
348	     * @param model the model
349	     * @param nodeName the last element of the path
350	     * @param uri the full uri of the node, must not be {@code null}.
351	     * @param method the method for the node, must not be {@code null}.
352	     * @param postData the data of the request body.
353	     * @return the name of the node to be used in the Site Map
354	     * @throws HttpMalformedHeaderException if the uri is not correct.
355	     * @throws NullPointerException if the uri or the method are {@code null}.
356	     * @since 2.10.0
357	     */
358	    public static String getLeafName(
359	            Model model, String nodeName, URI uri, String method, String postData)
360	            throws HttpMalformedHeaderException {
361	        Objects.requireNonNull(uri);
362	        Objects.requireNonNull(method);
363	        HttpMessage msg = new HttpMessage(uri);
364	        msg.getRequestHeader().setMethod(method);
365	        if (method.equalsIgnoreCase(HttpRequestHeader.POST)) {
366	            msg.getRequestBody().setBody(postData);
367	            msg.getRequestHeader().setContentLength(msg.getRequestBody().length());
368	        }
369	        return getLeafName(model, nodeName, msg);
370	    }
